import jinja2
from typing import Any, Optional


def render_template(template: str, context: Optional[Any] = None) -> str:
    """Render a template with provided variables and return the result as a string. template: The template string to render, e.g. 'Hello {{ name }}!' -> 'Hello World!'. context: The context variables to use for rendering, e.g. {'name': 'World'}."""
    try:
        env = jinja2.Environment()
        jinja_template = env.from_string(template)
        if context is None:
            return jinja_template.render()
        else:
            return jinja_template.render(context)
    except Exception as e:
        raise ValueError(f"Failed to render template: {str(e)}")
