import jinja2.environment
from typing import Iterator, Tuple, Optional


def iterate_tokens(source: str, name: Optional[str] = None, filename: Optional[str] = None, state: Optional[str] = None) -> Iterator[Tuple[int, str, str]]:
    """Tokenize a Jinja2 template source and return tokens as an iterator. source: The Jinja2 template source code to tokenize, name: Name of the template, filename: Filename of the template, state: Initial parsing state ('root', 'variable', or 'block'). Example: iterate_tokens('Hello {{ name }}', 'test') -> iterator of tokens."""
    try:
        env = jinja2.Environment()
        lexer = jinja2.environment.Lexer(env)
        return lexer.tokeniter(source, name, filename, state)
    except Exception as e:
        raise ValueError(f"Failed to tokenize template: {str(e)}")
