import jinja2
from typing import Union, Dict, Any


def parse_set_statement(source: str, environment: jinja2.Environment) -> Union[Dict[str, Any], None]:
    """Parse an assign statement from Jinja2 template source code. source: Jinja2 template string containing a set statement, environment: Jinja2 Environment object for parsing."""
    try:
        parser = jinja2.environment.Parser(environment, source)
        result = parser.parse_set()

        # Convert the parsed node to a dictionary representation
        if hasattr(result, 'target'):
            target_repr = str(result.target)
        else:
            target_repr = None

        if hasattr(result, 'node'):
            expr_repr = str(result.node) if result.node else None
        else:
            expr_repr = None

        if hasattr(result, 'body'):
            body_repr = [str(node) for node in result.body] if result.body else []
        else:
            body_repr = []

        return {
            "type": type(result).__name__,
            "target": target_repr,
            "expression": expr_repr,
            "body": body_repr,
            "line_number": result.lineno if hasattr(result, 'lineno') else None
        }
    except Exception as e:
        raise ValueError(f"Failed to parse set statement: {str(e)}")
