from jinja2 import nodes


def parse_from_import(source: str, name: str | None = None, filename: str | None = None) -> dict[str, str | list[dict[str, str]] | bool]:
    """Parse a Jinja2 from-import statement for importing specific items from templates. source: The Jinja2 template source code containing the from-import statement, name: The name of the template, filename: The filename of the template. Example: parse_from_import("from foo import bar, baz", "test") -> {"template": "foo", "names": [{"name": "bar"}, {"name": "baz"}], "with_context": false}"""
    try:
        environment = jinja2.Environment()
        parser = Parser(environment, source, name, filename)
        result = parser.parse_from()

        # Convert the FromImport node to a dictionary representation
        parsed_result = {
            "template": str(result.template),
            "names": [],
            "with_context": result.with_context
        }

        for item in result.names:
            if isinstance(item, tuple):
                parsed_result["names"].append({"name": item[0], "alias": item[1]})
            else:
                parsed_result["names"].append({"name": item})

        return parsed_result
    except Exception as e:
        raise ValueError(f"Failed to parse from-import statement: {str(e)}")
