import jinja2
from jinja2 import nodes
from jinja2.environment import Parser


def parse_test(environment: object, source: str, name: str | None = None, filename: str | None = None) -> dict[str, object]:
    """Parse a Jinja2 test assertion on an expression and return the test AST node. environment: The Jinja2 environment instance, source: The template source string containing the test assertion, name: The name of the template, filename: The filename of the template. Example: parse_test(env, "x is defined") -> {"type": "Test", "name": "defined", "args": [...]}"""
    try:
        parser = Parser(environment, source, name, filename)
        # Create a simple expression node to parse the test against
        expr_node = nodes.Name("test_expr", "load")
        result = parser.parse_test(expr_node)

        # Convert the AST node to a dictionary representation
        def node_to_dict(node):
            if hasattr(node, '__dict__'):
                result = {"type": type(node).__name__}
                for key, value in node.__dict__.items():
                    if key != 'lineno':  # Skip lineno for cleaner output
                        if isinstance(value, list):
                            result[key] = [node_to_dict(v) if hasattr(v, '__dict__') else v for v in value]
                        elif hasattr(value, '__dict__'):
                            result[key] = node_to_dict(value)
                        else:
                            result[key] = value
                return result
            return node

        return node_to_dict(result)
    except Exception as e:
        raise ValueError(f"Failed to parse test: {str(e)}")
