def reject_by_attribute(sequence: list[object], attribute: str, test_value: object) -> list[object]:
    """Rejects objects from a sequence by applying a test to the specified attribute of each object. sequence: array of objects to filter, attribute: name of attribute to test on each object, test_value: value to compare the attribute against. Example: reject_by_attribute([{'a': 1}, {'a': 2}], 'a', 1) -> [{'a': 2}]"""
    if not isinstance(sequence, list):
        raise ValueError("sequence must be a list")
    if not isinstance(attribute, str):
        raise ValueError("attribute must be a string")

    result = []
    for obj in sequence:
        if not hasattr(obj, attribute):
            # If object doesn't have the attribute, include it (since we're rejecting based on attribute value)
            result.append(obj)
        else:
            attr_value = getattr(obj, attribute)
            if attr_value != test_value:
                result.append(obj)

    return result
