import jinja2.nodes


def find_node_by_type(node: object, node_type: str) -> object | None:
    """Find the first node of a given type in the AST. node: The Jinja2 AST node to search within, node_type: The type of node to find (e.g., 'jinja2.nodes.Assign', 'jinja2.nodes.Output') -> The first matching node or None."""
    if not isinstance(node, jinja2.nodes.Node):
        raise ValueError("node must be a Jinja2 AST Node")

    # Parse the node_type string into actual class
    try:
        # Split the string to get module and class name
        module_and_class = node_type.rsplit('.', 1)
        if len(module_and_class) != 2:
            raise ValueError(f"Invalid node_type format: {node_type}")

        module_name, class_name = module_and_class

        # Import the module dynamically
        module = __import__(module_name, fromlist=[class_name])
        node_class = getattr(module, class_name)

        # Check if it's actually a node type
        if not issubclass(node_class, jinja2.nodes.Node):
            raise ValueError(f"{node_type} is not a valid Jinja2 node type")

    except (ImportError, AttributeError) as e:
        raise ValueError(f"Invalid node_type: {node_type}") from e

    # Use the find method
    try:
        return node.find(node_class)
    except Exception as e:
        raise ValueError(f"Error while searching for node type {node_type}: {str(e)}") from e
