import jinja2
from typing import Union, Optional


def compile_template(source: str, name: Optional[str] = None, filename: Optional[str] = None, raw: bool = False) -> Union[str, bytes]:
    """Compile a template source or AST into executable Python code. source: The template source code to compile, e.g. '{{ name }}' -> compiled code object. name: The load name of the template, filename: The estimated filename of the template on the file system, raw: If True, return a string with Python code; if False, return a code object."""
    try:
        env = jinja2.Environment()
        result = env.compile(source, name, filename, raw)
        if raw:
            return str(result)
        else:
            # Convert code object to bytes for serialization
            return bytes(result)
    except Exception as e:
        raise ValueError(f"Failed to compile template: {str(e)}")
