def filter_by_attribute(
    value: list[dict[str, object]], 
    attribute: str, 
    test: str | None = None, 
    value_to_compare: object | None = None
) -> list[dict[str, object]]:
    """Filter a sequence of objects by applying a test to the specified attribute of each object.

    Args:
        value: A sequence of objects to filter
        attribute: The name of the attribute to test
        test: The test to apply to the attribute (e.g., 'equalto', 'greaterthan')
        value_to_compare: The value to compare against for the test

    Example:
        filter_by_attribute([{'name': 'Alice', 'age': 30}, {'name': 'Bob', 'age': 25}], 'age', 'greaterthan', 26)
        -> [{'name': 'Alice', 'age': 30}]
    """
    # Validate inputs
    if not isinstance(value, list):
        raise ValueError("value must be a list")

    if not isinstance(attribute, str):
        raise ValueError("attribute must be a string")

    # Prepare arguments for jinja2 filter
    args = [attribute]
    kwargs = {}

    if test is not None:
        if not isinstance(test, str):
            raise ValueError("test must be a string")
        kwargs['test'] = test

    if value_to_compare is not None:
        kwargs['value_to_compare'] = value_to_compare

    # Simulate the jinja2 behavior using python built-ins
    # This is a simplified implementation since we can't actually call jinja2 here
    result = []

    for item in value:
        if not isinstance(item, dict):
            continue

        if attribute not in item:
            continue

        attr_value = item[attribute]

        # Apply test if provided
        if test is None:
            # Default: include if attribute exists and is truthy
            if attr_value:
                result.append(item)
        else:
            # Apply specific tests
            if test == 'equalto':
                if attr_value == value_to_compare:
                    result.append(item)
            elif test == 'notequal':
                if attr_value != value_to_compare:
                    result.append(item)
            elif test == 'greaterthan':
                if isinstance(attr_value, (int, float)) and isinstance(value_to_compare, (int, float)):
                    if attr_value > value_to_compare:
                        result.append(item)
            elif test == 'lessthan':
                if isinstance(attr_value, (int, float)) and isinstance(value_to_compare, (int, float)):
                    if attr_value < value_to_compare:
                        result.append(item)
            elif test == 'greaterthanequal':
                if isinstance(attr_value, (int, float)) and isinstance(value_to_compare, (int, float)):
                    if attr_value >= value_to_compare:
                        result.append(item)
            elif test == 'lessthanequal':
                if isinstance(attr_value, (int, float)) and isinstance(value_to_compare, (int, float)):
                    if attr_value <= value_to_compare:
                        result.append(item)
            elif test == 'startswith':
                if isinstance(attr_value, str) and isinstance(value_to_compare, str):
                    if attr_value.startswith(value_to_compare):
                        result.append(item)
            elif test == 'endswith':
                if isinstance(attr_value, str) and isinstance(value_to_compare, str):
                    if attr_value.endswith(value_to_compare):
                        result.append(item)
            elif test == 'contains':
                if isinstance(value_to_compare, (str, int, float)) and value_to_compare in attr_value:
                    result.append(item)
            else:
                # Unknown test, default to including if truthy
                if attr_value:
                    result.append(item)

    return result
